import raw from "../../../../content/games/logic.json";
import type { LogicItem } from "./logicLogic";

/** The bundled puzzles (content/games/logic.json, generated by tools/src/games/logic-gen.ts). */
export const LOGIC_ITEMS: LogicItem[] = (raw as { items: LogicItem[] }).items.filter(
  (i) => (i.level === 1 || i.level === 2 || i.level === 3) && i.options.includes(i.answer),
);
